function validate([order]) {
  if (!Array.isArray(order) || order.length < 1 || order.length > 100000) return 'order needs 1 to 100000 values.';
  const n = order.length;
  const seen = new Set();
  for (const v of order) {
    if (!Number.isInteger(v) || v < 1 || v > n) return 'Each value must be an integer from 1 to the length of order.';
    if (seen.has(v)) return 'order must not repeat a value.';
    seen.add(v);
  }
  return null;
}

