function maxDepthBST(order) {
  const n = order.length;
  const lower = new Array(n + 2);
  const higher = new Array(n + 2);
  for (let value = 0; value <= n + 1; value++) {
    lower[value] = value - 1;
    higher[value] = value + 1;
  }
  const below = new Array(n + 1);
  const above = new Array(n + 1);
  for (let i = n - 1; i >= 0; i--) {
    const value = order[i];
    below[value] = lower[value];
    above[value] = higher[value];
    higher[lower[value]] = higher[value];
    lower[higher[value]] = lower[value];
  }
  const depth = new Array(n + 2).fill(0);
  let deepest = 0;
  for (const value of order) {
    depth[value] = Math.max(depth[below[value]], depth[above[value]]) + 1;
    deepest = Math.max(deepest, depth[value]);
  }
  return deepest;
}

