function maxDepthBST(order) {
  // Build the tree node by node and record each node's depth as it is attached.
  const root = { val: order[0], left: null, right: null };
  let best = 1;
  for (let i = 1; i < order.length; i++) {
    let node = root;
    let level = 1;
    for (;;) {
      level++;
      const side = order[i] < node.val ? 'left' : 'right';
      if (node[side] === null) {
        node[side] = { val: order[i], left: null, right: null };
        break;
      }
      node = node[side];
    }
    best = Math.max(best, level);
  }
  return best;
}

