function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 8);
  const values = Array.from({ length: n }, (_, i) => i + 1);
  const shuffle = (list) => {
    for (let i = list.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
  };
  const shape = Math.floor(rand() * 5);
  if (shape === 0) return [values];
  if (shape === 1) return [values.reverse()];
  if (shape === 2) {
    // Alternate the smallest and largest remaining values: a long zigzag chain.
    const zigzag = [];
    let low = 1, high = n;
    while (low <= high) {
      zigzag.push(rand() < 0.5 ? low++ : high--);
    }
    return [zigzag];
  }
  if (shape === 3) {
    // Nearly sorted: a few random swaps break up the chain.
    const swaps = 1 + Math.floor(rand() * Math.max(1, n / 20));
    for (let s = 0; s < swaps; s++) {
      const i = Math.floor(rand() * n);
      const j = Math.floor(rand() * n);
      [values[i], values[j]] = [values[j], values[i]];
    }
    return [values];
  }
  return [shuffle(values)];
}
